import { authenticate, authorize } from "../../middlewares/auth";
import { validate } from "../../middlewares/validate";
import * as categoryController from "./category.controller";
import { createCategorySchema, updateCategorySchema } from "./category.schema";

const router = Router();

router.get("/", categoryController.list);
router.get("/:id", categoryController.getById);
router.post(
  "/",
  authenticate,
  authorize(Role.ADMIN),
  validate({ body: createCategorySchema }),
  categoryController.create,
);
router.patch(
  "/:id",
  authenticate,
  authorize(Role.ADMIN),
  validate({ body: updateCategorySchema }),
  categoryController.update,
);

router.delete(
  "/:id",
  authenticate,
  authorize(Role.ADMIN),
  categoryController.softDelete,
);

export default router;

import { z } from "zod";

export const createCategorySchema = z.object({
  name: z.string().min(2).max(120),
  slug: z
    .string()
    .min(2)
    .max(120)
    .regex(/^[a-z0-9-]+$/, "Slug must be lowercase alphanumeric with hyphens")
    .optional(),
  description: z.string().max(500).optional(),
  slaHours: z.coerce.number().int().min(1).max(720).default(72),
  departmentId: z.string().min(1),
});

export const updateCategorySchema = z.object({
  name: z.string().min(2).max(120).optional(),
  description: z.string().max(500).optional(),
  slaHours: z.coerce.number().int().min(1).max(720).optional(),
  departmentId: z.string().min(1).optional(),
  isActive: z.boolean().optional(),
});

import { prisma } from "../../config/prisma";
import { cacheDel, cacheGet, cacheSet } from "../../config/redis";
import { ApiError } from "../../utils/ApiError";
import { createAuditLog } from "../../utils/audit";

const CACHE_KEY = "categories:list";

const toSlug = (name: string) =>
  name
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");

export const createCategory = async (
  data: {
    name: string;
    slug?: string;
    description?: string;
    slaHours: number;
    departmentId: string;
  },
  actorId: string,
) => {
  const department = await prisma.department.findFirst({
    where: { id: data.departmentId, deletedAt: null },
  });
  if (!department) throw new ApiError(404, "Department not found");

  const category = await prisma.category.create({
    data: {
      name: data.name,
      slug: data.slug || toSlug(data.name),
      description: data.description,
      slaHours: data.slaHours,
      departmentId: data.departmentId,
    },
  });

  await cacheDel(CACHE_KEY);
  await createAuditLog({
    actorId,
    action: "CATEGORY_CREATED",
    entityType: "Category",
    entityId: category.id,
  });
  return category;
};

export const listCategories = async (departmentId?: string) => {
  const key = departmentId ? `${CACHE_KEY}:${departmentId}` : CACHE_KEY;
  const cached = await cacheGet<unknown[]>(key);
  if (cached) return cached;

  const categories = await prisma.category.findMany({
    where: {
      deletedAt: null,
      ...(departmentId ? { departmentId } : {}),
    },
    orderBy: { name: "asc" },
    select: {
      id: true,
      name: true,
      slug: true,
      description: true,
      slaHours: true,
      isActive: true,
      departmentId: true,
      department: { select: { id: true, name: true, code: true } },
    },
  });

  await cacheSet(key, categories, 120);
  return categories;
};

export const getCategoryById = async (id: string) => {
  const category = await prisma.category.findFirst({
    where: { id, deletedAt: null },
    include: { department: { select: { id: true, name: true, code: true } } },
  });
  if (!category) throw new ApiError(404, "Category not found");
  return category;
};

export const updateCategory = async (
  id: string,
  data: {
    name?: string;
    description?: string;
    slaHours?: number;
    departmentId?: string;
    isActive?: boolean;
  },
  actorId: string,
) => {
  const existing = await prisma.category.findFirst({ where: { id, deletedAt: null } });
  if (!existing) throw new ApiError(404, "Category not found");

  if (data.departmentId) {
    const department = await prisma.department.findFirst({
      where: { id: data.departmentId, deletedAt: null },
    });
    if (!department) throw new ApiError(404, "Department not found");
  }

  const category = await prisma.category.update({ where: { id }, data });
  await cacheDel(CACHE_KEY);
  await createAuditLog({
    actorId,
    action: "CATEGORY_UPDATED",
    entityType: "Category",
    entityId: id,
    metadata: data,
  });
  return category;
};


export const softDeleteCategory = async (id: string, actorId: string) => {
  const existing = await prisma.category.findFirst({ where: { id, deletedAt: null } });
  if (!existing) throw new ApiError(404, "Category not found");

  const category = await prisma.category.update({
    where: { id },
    data: { deletedAt: new Date(), isActive: false },
  });
  await cacheDel(CACHE_KEY);
  await createAuditLog({
    actorId,
    action: "CATEGORY_SOFT_DELETED",
    entityType: "Category",
    entityId: id,
  });
  return category;
};

import type { Request, Response } from "express";
import { asyncHandler } from "../../utils/asyncHandler";
import { sendSuccess } from "../../utils/ApiResponse";
import { getPagination } from "../../utils/pagination";
import * as complaintService from "./complaint.service";

export const create = asyncHandler(async (req: Request, res: Response) => {
  const data = await complaintService.createComplaint(req.user!.id, req.body);
  return sendSuccess(res, data, "Complaint created", 201);
});

export const list = asyncHandler(async (req: Request, res: Response) => {
  const { page, limit } = getPagination(req);
  const data = await complaintService.listComplaints(req.user!, {
    page,
    limit,
    status: req.query.status as never,
    priority: req.query.priority as never,
    departmentId: req.query.departmentId as string | undefined,
    categoryId: req.query.categoryId as string | undefined,
    search: req.query.search as string | undefined,
    sortBy: req.query.sortBy as never,
    sortOrder: req.query.sortOrder as never,
  });
  return sendSuccess(res, data, "Complaints fetched");
});

export const getById = asyncHandler(async (req: Request, res: Response) => {
  const data = await complaintService.getComplaintById(req.params.id, req.user!);
  return sendSuccess(res, data, "Complaint fetched");
});

export const update = asyncHandler(async (req: Request, res: Response) => {
  const data = await complaintService.updateComplaint(req.params.id, req.user!, req.body);
  return sendSuccess(res, data, "Complaint updated");
});

export const remove = asyncHandler(async (req: Request, res: Response) => {
  const data = await complaintService.softDeleteComplaint(req.params.id, req.user!);
  return sendSuccess(res, data, "Complaint soft-deleted");
});

export const assign = asyncHandler(async (req: Request, res: Response) => {
  const data = await complaintService.assignComplaint(
    req.params.id,
    req.user!,
    req.body.staffId,
    req.body.note,
  );
  return sendSuccess(res, data, "Complaint assigned");
});

export const updateStatus = asyncHandler(async (req: Request, res: Response) => {
  const data = await complaintService.updateComplaintStatus(
    req.params.id,
    req.user!,
    req.body.status,
    req.body.note,
    req.body.rejectionReason,
  );
  return sendSuccess(res, data, "Complaint status updated");
});

export const cancel = asyncHandler(async (req: Request, res: Response) => {
  const data = await complaintService.cancelComplaint(req.params.id, req.user!, req.body.note);
  return sendSuccess(res, data, "Complaint cancelled");
});

export const myAssigned = asyncHandler(async (req: Request, res: Response) => {
  const { page, limit } = getPagination(req);
  const data = await complaintService.getMyAssigned(req.user!.id, page, limit);
  return sendSuccess(res, data, "Assigned complaints fetched");
});

export const feedback = asyncHandler(async (req: Request, res: Response) => {
  const data = await complaintService.submitFeedback(
    req.params.id,
    req.user!.id,
    req.body.rating,
    req.body.comment,
  );
  return sendSuccess(res, data, "Feedback submitted", 201);
});

